package com.android.tools.lint.checks

import com.android.tools.lint.detector.api.Category
import com.android.tools.lint.detector.api.Detector
import com.android.tools.lint.detector.api.Implementation
import com.android.tools.lint.detector.api.Issue
import com.android.tools.lint.detector.api.JavaContext
import com.android.tools.lint.detector.api.JavaElementVisitor
import com.android.tools.lint.detector.api.Scope
import com.android.tools.lint.detector.api.Severity
import com.intellij.psi.PsiElement
import com.intellij.psi.PsiMethod

class WrongConstructorDetector : Detector(), Detector.JavaPsiScanner {
    override fun getApplicablePsiTypes(): List<Class<out PsiElement>> = listOf(PsiMethod::class.java)

    override fun createPsiVisitor(context: JavaContext): JavaElementVisitor = object : JavaElementVisitor() {
        override fun visitMethod(method: PsiMethod) {
            super.visitMethod(method)
            if (method.isConstructor) return

            val name = method.name ?: return
            val className = method.containingClass?.name ?: return

            if (name == className) {
                context.report(
                    ISSUE,
                    method,
                    context.getNameLocation(method),
                    "This method has the same name as the class and therefore looks like it should be a constructor, but it has a return type"
                )
            }
        }
    }

    companion object {
        @JvmField
        val ISSUE: Issue = Issue.create(
            id = "NotConstructor",
            briefDescription = "Not a Constructor",
            explanation = "Methods that have the same name as the containing class but are not constructors are likely a mistake; constructors do not have return types.",
            category = Category.CORRECTNESS,
            priority = 4,
            severity = Severity.WARNING,
            implementation = Implementation(WrongConstructorDetector::class.java, Scope.JAVA_FILE_SCOPE)
        )
    }
}
